#include <unordered_map>
using namespace std;

class OrderManagementSystem {
    unordered_map<int, int> orders;
    long long total_val = 0;
public:
    OrderManagementSystem() {}

    void addOrder(int order_id, int price) {
        if (orders.count(order_id)) {
            total_val -= orders[order_id];
        }
        orders[order_id] = price;
        total_val += price;
    }

    void cancelOrder(int order_id) {
        if (orders.count(order_id)) {
            total_val -= orders[order_id];
            orders.erase(order_id);
        }
    }

    int getTotalOrderValue() {
        return total_val;
    }
};

import java.util.*;

class OrderManagementSystem {
    private Map<Integer, Integer> orders = new HashMap<>();
    private long totalValue = 0;

    public OrderManagementSystem() {}

    public void addOrder(int orderId, int price) {
        if (orders.containsKey(orderId)) {
            totalValue -= orders.get(orderId);
        }
        orders.put(orderId, price);
        totalValue += price;
    }

    public void cancelOrder(int orderId) {
        if (orders.containsKey(orderId)) {
            totalValue -= orders.remove(orderId);
        }
    }

    public int getTotalOrderValue() {
        return (int)totalValue;
    }
}

var OrderManagementSystem = function() {
    this.orders = new Map();
    this.totalVal = 0;
};

OrderManagementSystem.prototype.addOrder = function(order_id, price) {
    if (this.orders.has(order_id)) {
        this.totalVal -= this.orders.get(order_id);
    }
    this.orders.set(order_id, price);
    this.totalVal += price;
};

OrderManagementSystem.prototype.cancelOrder = function(order_id) {
    if (this.orders.has(order_id)) {
        this.totalVal -= this.orders.get(order_id);
        this.orders.delete(order_id);
    }
};

OrderManagementSystem.prototype.getTotalOrderValue = function() {
    return this.totalVal;
};
